<?php $page='settings';$title='Settings';require_once __DIR__.'/includes/functions.php';require_login();$uid=$_SESSION['user_id'];$q=$pdo->prepare('SELECT * FROM users WHERE id=?');$q->execute([$uid]);$user=$q->fetch();verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';if($action==='export'){export_sql($pdo);}elseif($action==='profile'){$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');if($name!==''&&filter_var($email,FILTER_VALIDATE_EMAIL)){try{$q=$pdo->prepare('UPDATE users SET full_name=?,email=? WHERE id=?');$q->execute([$name,$email,$uid]);$_SESSION['full_name']=$name;set_flash('Profile updated.');}catch(PDOException $e){set_flash('That email address is already in use.','error');}}else set_flash('Please enter a valid name and email.','error');}elseif($action==='password'){$old=$_POST['current_password']??'';$new=$_POST['new_password']??'';if(password_verify($old,$user['password'])&&strlen($new)>=8){$q=$pdo->prepare('UPDATE users SET password=? WHERE id=?');$q->execute([password_hash($new,PASSWORD_DEFAULT),$uid]);set_flash('Password changed successfully.');}else set_flash('Current password is incorrect or new password is too short.','error');}header('Location: settings.php');exit;}require 'includes/header.php';?>
<div class="page-head"><div><h1>Settings</h1><p>Manage your account information and password.</p></div></div><div class="two-col"><div class="card form-card"><h3>Profile Information</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="profile"><div class="field"><label>Full Name</label><input name="full_name" required value="<?=e($user['full_name'])?>"></div><div class="field"><label>Username</label><input value="<?=e($user['username'])?>" disabled></div><div class="field"><label>Email</label><input type="email" name="email" required value="<?=e($user['email'])?>"></div><button class="btn">Save Profile</button></form></div><div class="card form-card"><h3>Change Password</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="password"><div class="field"><label>Current Password</label><input type="password" name="current_password" required></div><div class="field"><label>New Password</label><input type="password" name="new_password" minlength="8" required></div><button class="btn">Update Password</button></form></div></div><?php if(is_admin($pdo)):?><div class="card form-card"><h3>Admin: Database Export</h3><p class="muted">Download a full backup of the <b>budget_tracker</b> database (all tables and records) as a .sql file. You can re-import it in phpMyAdmin.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="export"><button class="btn">⬇ Export SQL Database</button></form></div><?php endif;?><?php require 'includes/footer.php';?>
